        for (int i = 0; i < numbers.size(); i++) {
            segments[i] = numbers.get(i);
        }
        return new ModuleVersion(value, segments);
    }

    @Override
    public int compareTo(ModuleVersion other) {
        int n = Math.max(segments.length, other.segments.length);
