package com.example.starter.firmware.api;

import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

/**
 * 设备登记请求。groupName 可选，缺省为未分组（null），登记后不可修改。
 */
public record RegisterDeviceRequest(
        @NotBlank @Size(max = 64) String requestId,
        @NotBlank @Size(max = 64) String deviceId,
        @NotBlank @Size(max = 64) String model,
        @NotBlank @Size(max = 64) String currentVersion,
        @Min(0) @Max(99) int bucketNo,
        @Size(max = 64) String groupName) {

    public RegisterDeviceRequest(String requestId, String deviceId, String model,
                                 String currentVersion, int bucketNo) {
        this(requestId, deviceId, model, currentVersion, bucketNo, null);
    }
}

package com.example.starter.firmware.api;

import com.example.starter.firmware.domain.Device;

/**
 * 设备视图。groupName 为 null 表示设备未分组。
 */
public record DeviceView(String deviceId, String model, String currentVersion, int bucketNo,
                         String groupName) {

    public static DeviceView of(Device device) {
        return new DeviceView(device.deviceId(), device.model(), device.currentVersion(),
                device.bucketNo(), device.groupName());
    }
}

package com.example.starter.firmware.api;

import com.example.starter.firmware.domain.ReleaseOrder;
import com.example.starter.firmware.domain.RolloutTask;

import java.util.List;

/**
 * 投放任务视图。模块兼容字段为下发时固化的证据快照，后续矩阵修订/设备重报不改写：
 * moduleSummary 为设备模块摘要（按模块名排序）；matrixVersion/exemptionVersion 为固化版本，可能为 null。
 */
public record TaskView(long taskId, long releaseId, String deviceId, String status,
                       String fromVersion, String toVersion,
                       List<ModuleEntryView> moduleSummary, Integer matrixVersion,
                       Integer exemptionVersion) {

    public static TaskView of(RolloutTask task, ReleaseOrder order, List<ModuleEntryView> moduleSummary) {
        return new TaskView(task.id(), task.releaseId(), task.deviceId(), task.status().name(),
                order.fromVersion(), order.toVersion(), moduleSummary,
                task.matrixVersion(), task.exemptionVersion());
    }
}

package com.example.starter.firmware.api;

/**
 * 模块版本条目（设备清单与任务固化摘要共用）。
 */
public record ModuleEntryView(String module, String version) {
}

