private void expectOk(MvcResult result) throws Exception {
    assertThat(result.getResponse().getStatus())
            .as("期望 200，实际: %s %s", result.getResponse().getStatus(),
                    result.getResponse().getContentAsString())
            .isEqualTo(200);
}

private JsonNode json(MvcResult result) throws Exception {
    return objectMapper.readTree(result.getResponse().getContentAsString());
}

private void registerDevice(String requestId, String deviceId, String group) throws Exception {
    String groupJson = group == null ? "null" : "\"" + group + "\"";
    MvcResult result = postJson("/api/devices",
            "{\"requestId\":\"%s\",\"deviceId\":\"%s\",\"model\":\"m1\",\"currentVersion\":\"1.0.0\","
                    + "\"bucketNo\":5,\"groupName\":%s}".formatted(requestId, deviceId, groupJson));
    expectOk(result);
}

private long createRelease(String requestId, int ratio, int floor, int threshold) throws Exception {
    MvcResult result = postJson("/api/releases",
            "{\"requestId\":\"%s\",\"model\":\"m1\",\"fromVersion\":\"1.0.0\",\"toVersion\":\"2.0.0\","
                    + "\"ratio\":%d,\"sampleFloor\":%d,\"failureThresholdPercent\":%d}"
