void 豁免左闭右开_到期时刻恰好失效_前一秒仍生效() throws Exception {
    registerMatrix("r-m", "2.0.0", "[{\"module\":\"m\",\"minVersion\":\"1.0\"}]", "[]");
    registerDevice("r-d1", "d1", "beta");
    registerDevice("r-d2", "d2", "beta");
