    // T0+100：恰好到期，左闭右开区间关闭，阻断且豁免版本为 null
    advanceSeconds(1);
    MvcResult atExpiry = postJson("/api/devices/d2/pull", "{\"requestId\":\"r-pull-expiry\"}");
